Here is the commit message:
kdb: use correct pointer when 'btc' calls 'btt'

On a powerpc 8xx, 'btc' fails as follows:

Entering kdb (current=0x(ptrval), pid 282) due to Keyboard Entry
kdb> btc
btc: cpu status: Currently on cpu 0
Available cpus: 0
kdb_getarea: Bad address 0x0

when booting the kernel with 'debug_boot_weak_hash', it fails as well

Entering kdb (current=0xba99ad80, pid 284) due to Keyboard Entry
kdb> btc
btc: cpu status: Currently on cpu 0
Available cpus: 0
kdb_getarea: Bad address 0xba99ad80

On other platforms, Oopses have been observed too, see
https://github.com/linuxppc/linux/issues/139

This is due to btc calling 'btt' with %p pointer as an argument.

This patch replaces %p by %px to get the real pointer value as
expected by 'btt'

Fixes: ad67b74d2469 ("printk: hash addresses printed with %p")
Cc: <stable@vger.kernel.org>
Signed-off-by: Christophe Leroy <christophe.leroy@c-s.fr>
Reviewed-by: Daniel Thompson <daniel.thompson@linaro.org>
Signed-off-by: Daniel Thompson <daniel.thompson@linaro.org>

Here is the root cause:
The bug occurs because the `btc` command calls the `btt` function with a pointer formatted using `%p`, which does not provide the correct pointer value on certain platforms, leading to a "Bad address" error. The correct format specifier `%px` should be used to ensure the actual pointer value is printed and passed correctly to the `btt` function.

Here is the patch:

 int
 kdb_bt(int argc, const char **argv)
 {
 	int diag;
 	int argcount = 5;
 	int btaprompt = 1;
 	int nextarg;
 	unsigned long addr;
 	long offset;

 	/* Prompt after each proc in bta */
 	kdbgetintenv("BTAPROMPT", &btaprompt);

 	if (strcmp(argv[0], "bta") == 0) {
 		struct task_struct *g, *p;
 		unsigned long cpu;
 		unsigned long mask = kdb_task_state_string(argc ? argv[1] :
 							   NULL);
 		if (argc == 0)
 			kdb_ps_suppressed();
 		/* Run the active tasks first */
 		for_each_online_cpu(cpu) {
 			p = kdb_curr_task(cpu);
 			if (kdb_bt1(p, mask, argcount, btaprompt))
 				return 0;
 		}
 		/* Now the inactive tasks */
 		kdb_do_each_thread(g, p) {
 			if (KDB_FLAG(CMD_INTERRUPT))
 				return 0;
 			if (task_curr(p))
 				continue;
 			if (kdb_bt1(p, mask, argcount, btaprompt))
 				return 0;
 		} kdb_while_each_thread(g, p);
 	} else if (strcmp(argv[0], "btp") == 0) {
 		struct task_struct *p;
 		unsigned long pid;
 		if (argc != 1)
 			return KDB_ARGCOUNT;
 		diag = kdbgetularg((char *)argv[1], &pid);
 		if (diag)
 			return diag;
 		p = find_task_by_pid_ns(pid, &init_pid_ns);
 		if (p) {
 			kdb_set_current_task(p);
 			return kdb_bt1(p, ~0UL, argcount, 0);
 		}
 		kdb_printf("No process with pid == %ld found\n", pid);
 		return 0;
 	} else if (strcmp(argv[0], "btt") == 0) {
 		if (argc != 1)
 			return KDB_ARGCOUNT;
 		diag = kdbgetularg((char *)argv[1], &addr);
 		if (diag)
 			return diag;
 		kdb_set_current_task((struct task_struct *)addr);
 		return kdb_bt1((struct task_struct *)addr, ~0UL, argcount, 0);
 	} else if (strcmp(argv[0], "btc") == 0) {
 		unsigned long cpu = ~0;
 		struct task_struct *save_current_task = kdb_current_task;
 		char buf[80];
 		if (argc > 1)
 			return KDB_ARGCOUNT;
 		if (argc == 1) {
 			diag = kdbgetularg((char *)argv[1], &cpu);
 			if (diag)
 				return diag;
 		}
 		/* Recursive use of kdb_parse, do not use argv after
 		 * this point */
 		argv = NULL;
 		if (cpu != ~0) {
 			if (cpu >= num_possible_cpus() || !cpu_online(cpu)) {
 				kdb_printf("no process for cpu %ld\n", cpu);
 				return 0;
 			}
-			sprintf(buf, "btt 0x%p\n", KDB_TSK(cpu));
+			sprintf(buf, "btt 0x%px\n", KDB_TSK(cpu));
 			kdb_parse(buf);
 			return 0;
 		}
 		kdb_printf("btc: cpu status: ");
 		kdb_parse("cpu\n");
 		for_each_online_cpu(cpu) {
-			sprintf(buf, "btt 0x%p\n", KDB_TSK(cpu));
+			sprintf(buf, "btt 0x%px\n", KDB_TSK(cpu));
 			kdb_parse(buf);
 			touch_nmi_watchdog();
 		}
 		kdb_set_current_task(save_current_task);
 		return 0;
 	} else {
 		if (argc) {
 			nextarg = 1;
 			diag = kdbgetaddrarg(argc, argv, &nextarg, &addr,
 					     &offset, NULL);
 			if (diag)
 				return diag;
 			kdb_show_stack(kdb_current_task, (void *)addr);
 			return 0;
 		} else {
 			return kdb_bt1(kdb_current_task, ~0UL, argcount, 0);
 		}
 	}

 	/* NOTREACHED */
 	return 0;
 }
